// 8 synthetic invoices (TEXT). Fake vendors, example.com-style emails, fake amounts.
// RUN is embedded in invoice numbers so every test run has unique content (hashes differ between runs).
const RUN = Date.now().toString(36).slice(-4).toUpperCase();
const day = n => { const d = new Date(); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const dmy = n => { const [y, m, d] = day(n).split('-'); return d + '/' + m + '/' + y; };

